  "Prima della firma prepara il verbale con verifiche, esito ed eventuali riserve. La richiesta collegata al solo ordine non contiene un documento da firmare.": "قبل السينياتور وجد المحضر فيه التحققات، النتيجة والتحفظات إلا كانو. الطلب المربوط غير بالكوميسا ما فيهش وثيقة باش تتسينا.",
