  "Tocca chi era in cantiere e scrivi le sue ore. Chi ha già mandato il suo rapportino non va segnato di nuovo.": "تيكي على اللي كان فالشانطي وكتب السوايع ديالو. اللي ديجا صيفط الرابورتينو ديالو ما خاصوش يتسجل مرة أخرى.",
  "Tocca chi della tua squadra era in cantiere e scrivi le sue ore. Chi ha già mandato il suo rapportino non va segnato di nuovo.": "تيكي على اللي كان فالشانطي من الإيكيپ ديالك وكتب السوايع ديالو. اللي ديجا صيفط الرابورتينو ديالو ما خاصوش يتسجل مرة أخرى.",
