  "Infisso · esterno telaio": "السيرامنتو · التيلايو من برا",
  "Pianta e sezione schematiche, non in scala. Quote autonome: nessuna tolleranza o misura d’ordine dedotta. Posizione nel muro, giochi e spessori dei profili sono illustrativi.": "رسم من الفوق ومن الجنب، ماشي بالسكالا. قياسات بوحدهم: ما كيتحسب حتى تولورانس ولا قياس ديال الكوموند. البلاصة فالحيط، الجوكو والسمك ديال البروفيلات غير للتوضيح.",
  "Controtelaio da rilevare: non viene aggiunto automaticamente al disegno.": "الكونتروتيلايو خاصو يتقاس: ما كيتزادش أوتوماتيكيا فالرسم.",
  "Controtelaio non previsto ma con misure inserite: verifica la discordanza prima di ordinare.": "الكونتروتيلايو ما مبرمجش ولكن عندو قياسات: راجع هاد التناقض قبل ما تكوموندي.",
  "Larghezze": "العروض",
  "Altezze": "الطولات",
  "Vano rustico dell’abaco diverso dalle misure principali del foro: verifica quale rilievo è aggiornato.": "الفورو الخام فالأباكو ماشي بحال القياسات الرئيسية ديال الفورو: شوف أشمن قياسات هوما الجداد.",
  "Verso interno / esterno non confermato: nessun arco a battente in pianta.": "الاتجاه لداخل / لبرا ما تأكدش: ما كنرسموش الدورة ديال الدفة من الفوق.",
  "Ribalta, vasistas e libro: vedere il simbolo sul frontale; cinematismo e ingombri esecutivi richiedono la scheda del produttore.": "الريبالطا، الفازيستاس والكتاب: شوف العلامة فالرسم من القدام؛ الحركة والقياسات التنفيذية خاصهم الفيشة ديال الفابريكا.",
  "Sagoma tonda / ovale: pianta e sezione restano indicative; allegare il dettaglio del produttore.": "شكل مدور / بيضاوي: الرسم من الفوق ومن الجنب غير تقريبي؛ زيد التفصيل ديال الفابريكا.",
  "Profondità telaio maggiore dello spessore muro rilevato: verificare sporgenze e riferimento di misura.": "العمق ديال التيلايو كبر من السمك ديال الحيط اللي تقاس: راجع شحال خارج والمرجع ديال القياس.",
  "Pianta · apertura e posa": "من الفوق · الفتحة والتركيب",
  "ESTERNO in alto · INTERNO in basso. Cerniere e scorrimento riferiti al frontale interno; ante e posizioni schematiche, non sono luci nette di passaggio.": "البرا لفوق · الداخل لتحت. الشارنيرات والسلايد على حساب الوجه الداخلي؛ الدفات والبلايص غير رسم، ماشي الفتحات الصافية ديال الدوزان.",
  "Sezione verticale · telaio e raccordi": "القطعة العمودية · التيلايو والوصلات",
  "Schema separato dal telo. Nessuna maggiorazione o tolleranza di taglio automatica. Manovra del telaio distinta dal comando del telo.": "رسم بوحدو على التيلو. ما كاين حتى زيادة ولا تولورانس ديال القطيع أوتوماتيكيا. التشغيل ديال التيلايو ماشي هو التشغيل ديال التيلو.",
  "Telaio chiuso · ingombro frontale": "التيلايو مسدود · القياس من القدام",
  "Quote esterne del telaio a sporgere, non dimensioni del telo. Profili illustrativi.": "القياسات من برا ديال التيلايو اللي كيخرج، ماشي القياسات ديال التيلو. البروفيلات غير للتوضيح.",
  "Apertura a sporgere · vista laterale": "الفتحة لبرا · من الجنب",
  "Per lo schema aperto rileva lunghezza guida mobile e sporgenza orizzontale positiva, minore della lunghezza. Nessun angolo predefinito.": "باش ترسم وهو محلول قيس الطول ديال السكة اللي كتحرك وشحال كيخرج فالعرض (أكبر من الصفر، وصغر من الطول). ما كاين حتى زاوية مفروضة.",
  "La sporgenza aperta supera lo spazio esterno libero rilevato: verificare interferenze e arresti.": "شحال كيخرج ملي محلول كيفوت البلاصة الخاوية اللي تقاسات برا: راجع شنو كيضرب فيه والستوبات.",
  "Manovra del telaio a sporgere da rilevare; non viene dedotta dal motore della tapparella.": "التشغيل ديال التيلايو اللي كيخرج خاصو يتقاس؛ ما كيتحسبش من الموطور ديال التاباريلا.",
  "Ingombro monoblocco, luce interna, foro e telaio del serramento sono quote autonome: nessuna misura finita è ricavata per differenza. Le figure non sono sezioni esecutive.": "القياس ديال المونوبلوكو، الفتحة الداخلية، الفورو والتيلايو ديال السيرامنتو كل وحدة بوحدها: حتى قياس مكمّل ما كيتحسب بالفرق. الرسومات ماشي قطع تنفيذية.",
  "I complementi restano schede tecniche del sistema, non forniture aggiuntive automatiche. Verifica inclusioni ed esclusioni prima del preventivo.": "الزيادات كيبقاو فيشات تقنية ديال السيستيم، ماشي فورنيتورات زايدين أوتوماتيكيا. راجع آش داخل وآش ما داخلش قبل الدوفي.",
  "Monoblocco · ingombro esterno": "المونوبلوكو · القياس من برا",
  "Parti evidenziate solo se dichiarate incluse. Frontali rilevati rappresentati; in assenza, spessori simbolici. La luce interna resta una quota autonoma.": "الطرفات كيتبينو غير إلا تقال بلي داخلين. القياسات من القدام اللي تقاسو مرسومين؛ إلا ما كاينينش، سمك رمزي. الفتحة الداخلية كتبقى قياس بوحدو.",
  "Ingombro esterno del monoblocco incompleto: rileva larghezza e altezza totali, senza usare quelle dell’infisso.": "القياس من برا ديال المونوبلوكو ناقص: قيس العرض والطول الكاملين، بلا ما تخدم بديال السيرامنتو.",
  "Monoblocco · luce interna autonoma": "المونوبلوكو · الفتحة الداخلية بوحدها",
  "Luce interna dichiarata, su scala propria: non è la misura d’ordine del serramento.": "الفتحة الداخلية المكتوبة، بسكالا ديالها: ماشي القياس ديال الكوموند ديال السيرامنتو.",
  "Luce interna non inferiore all’ingombro esterno del monoblocco: verificare i riferimenti delle quote.": "الفتحة الداخلية ما صغراش على القياس من برا ديال المونوبلوكو: راجع المراجع ديال القياسات.",
  "Monoblocco: modello e sezione esecutiva del produttore da acquisire.": "المونوبلوكو: الموديل والقطعة التنفيذية ديال الفابريكا خاصهم يتجابو.",
  "Monoblocco: componenti inclusi da confermare, nessuna integrazione viene presunta.": "المونوبلوكو: القطع اللي داخلين خاصهم يتأكدو، ما كنفترضو حتى زيادة.",
  "Monoblocco e telaio a sporgere: verificare compatibilità, fissaggi e accessibilità sulla sezione del produttore.": "المونوبلوكو والتيلايو اللي كيخرج: راجع واش كيتوافقو، التثبيت والدخول على القطعة ديال الفابريكا.",
