  "Ingombro frontale delle guide incompatibile con il campo: quote da verificare, sagoma dei profili solo illustrativa.": "القياس من القدام ديال السكك ما كيتوافقش مع الخانة: القياسات خاصهم يتراجعو، الشكل ديال البروفيلات غير للتوضيح.",
