  "Spessori e ingombri di posa": "السمك والقياسات ديال التركيب",
  "Quote in mm. Rettangoli di ingombro e confronti di profondità, non sezioni esecutive dei profili. Ogni dettaglio ha scala propria. Quote assenti non dedotte; misure del vano e del prodotto restano invariate. L’assenza di avvisi non certifica la compatibilità.": "القياسات بالمم. مستطيلات ديال البلاصة ومقارنة ديال العمق، ماشي قطع تنفيذية ديال البروفيلات. كل تفصيل عندو السكالا ديالو. القياسات اللي ناقصين ما كيتحسبوش؛ القياسات ديال الفورو والبرودوي كيبقاو كيف هوما. إلا ما كاين حتى تنبيه، ماشي معناها كيتوافقو.",
