  "Servono misure sul piano della falda, non la proiezione orizzontale.": "خاصك القياسات على السقف المايل، ماشي الإسقاط الأفقي.",
  "Inserisci dimensioni falda e numero intero di moduli (1–200).": "دخل القياسات ديال السقف والعدد الصحيح ديال البانوات (1–200).",
  "Conferma fascia di bordo e interspazio da progetto, anche se pari a zero.": "أكّد الشريط ديال الطرف والفراغ بين البانوات من المشروع، واخا يكونو صفر.",
  "Dimensioni incompatibili o griglia eccessiva: verifica le misure.": "القياسات ما كيتوافقوش ولا الشبكة كبيرة بزاف: راجع القياسات.",
  "Disposizione moduli da preparare e verificare sul rilievo.": "التوزيع ديال البانوات خاصو يتوجد ويتراجع فالقياسات.",
