  "Disposizione sul piano della falda": "التوزيع على السقف المايل",
  "Quote sul piano di posa. Ostacoli come ingombri rilevati, non come ombre calcolate. Schema preliminare, non progetto esecutivo.": "القياسات على السطح ديال التركيب. العوائق كبلايص تقاسو، ماشي كظل محسوب. رسم أولي، ماشي مشروع تنفيذي.",
  "Arrivo": "الوصول",
  "Pianta e spazi liberi rilevati": "الرسم من الفوق والبلايص الخاويين اللي تقاسو",
