  "Verifica tecnica e riferimento documentale da completare; il rilievo non certifica conformità o compatibilità.": "المراجعة التقنية والمرجع ديال الوثيقة خاصهم يتكملو؛ القياسات ما كيأكدوش المطابقة ولا التوافق.",
  "Disposizione sul piano inclinato non confermata: non usare la proiezione orizzontale come superficie di posa.": "التوزيع على السقف المايل ما تأكدش: ما تخدمش بالإسقاط الأفقي كسطح ديال التركيب.",
  "Struttura e fissaggi da verificare: nessun carico o ancoraggio dimensionato automaticamente.": "الهيكل والتثبيت خاصهم يتراجعو: حتى حمل ولا تثبيت ما كيتحسب أوتوماتيكيا.",
