  "Compatibilità pompa di calore, caldaia e kit ibrido da documentare.": "التوافق ديال البومبة ديال الحرارة، الشوديير والكيت الهيبريد خاصو يتوثق.",
  "C da rilevare": "C خاصو يتقاس",
  "Schema illustrativo non in scala. Le quote numeriche sono quelle rilevate; il pannello frontale indica la forma, non conferma il lato d’ispezione.": "رسم للتوضيح ماشي بالسكالا. الأرقام هوما القياسات اللي تقاسو؛ البانو من القدام كيبين الشكل، ما كيأكدش الجهة ديال الكشف.",
